import { Container, Grid, Typography, Card, CardContent } from "@mui/material";
import "./Skill.css";
import React from "react";

export default function Skill() {
  const skills = {
    "Programming Languages": [
      {
        name: "PHP",
        icon: (
          <svg className="icon icon-php">
            <use xlinkHref="#icon-php"></use>
          </svg>
        ),
      },
      {
        name: "Java",
        icon: (
          <svg className="icon icon-java">
            <use xlinkHref="#icon-java"></use>
          </svg>
        ),
      },
      {
        name: "JavaScript",
        icon: (
          <svg className="icon icon-javascript">
            <use xlinkHref="#icon-javascript"></use>
          </svg>
        ),
      },
      {
        name: "Python",
        icon: (
          <svg className="icon icon-php">
            <use xlinkHref="#icon-python"></use>
          </svg>
        ),
      },
      {
        name: "C++",
        icon: (
          <svg className="icon icon-php">
            <use xlinkHref="#icon-c"></use>
          </svg>
        ),
      },
    ],
    "Back End": [
      {
        name: "React",
        icon: (
          <svg className="icon icon-java">
            <use xlinkHref="#icon-java"></use>
          </svg>
        ),
      },
      {
        name: "Laravel",
        icon: (
            <svg className="icon icon-java">
            <use xlinkHref="#icon-java"></use>
          </svg>
        ),
      },
      {
        name: "Code Igniter",
        icon: (
            <svg className="icon icon-java">
            <use xlinkHref="#icon-java"></use>
          </svg>
        ),
      },
    ],
    "Front End": [
      {
        name: "Ract JS",
        icon: (
          <svg className="icon icon-java">
            <use xlinkHref="#icon-java"></use>
          </svg>
        ),
      },
      {
        name: "Bootstrap",
        icon: (
            <svg className="icon icon-java">
            <use xlinkHref="#icon-java"></use>
          </svg>
        ),
      },
      {
        name: "Material UI",
        icon: (
            <svg className="icon icon-java">
            <use xlinkHref="#icon-java"></use>
          </svg>
        ),
      },
      {
        name: "Tailwinds",
        icon: (
            <svg className="icon icon-java">
            <use xlinkHref="#icon-java"></use>
          </svg>
        ),
      },
    ],
    "Tools": [
      {
        name: "Git",
        icon: (
          <svg className="icon icon-java">
            <use xlinkHref="#icon-java"></use>
          </svg>
        ),
      },
      {
        name: "Visual Studio Code",
        icon: (
            <svg className="icon icon-java">
            <use xlinkHref="#icon-java"></use>
          </svg>
        ),
      },
      {
        name: "Github",
        icon: (
            <svg className="icon icon-java">
            <use xlinkHref="#icon-java"></use>
          </svg>
        ),
      },
      {
        name: "GitLab",
        icon: (
            <svg className="icon icon-java">
            <use xlinkHref="#icon-java"></use>
          </svg>
        ),
      },
      {
        name: "MySQL",
        icon: (
            <svg className="icon icon-java">
            <use xlinkHref="#icon-java"></use>
          </svg>
        ),
      },
      {
        name: "XAMPP",
        icon: (
            <svg className="icon icon-java">
            <use xlinkHref="#icon-java"></use>
          </svg>
        ),
      },
    ],
  };
  const nameArray = ["Programming Languages", "Back End","Front End", "Tools"];

  return (
    <div>
      <Container
        id={"skill"}
        style={{
          paddingTop: "2rem",
          paddingBottom: "2rem",
          marginBottom: "2rem",
          borderRadius: "10px",
        }}
      >
        <Typography
          variant="h2"
          sx={{
            fontWeight: "bold",
            fontSize: "3rem",
            color: "text",
            marginBottom: "1rem",
            textAlign: "center",
          }}
        >
          Skills
        </Typography>
        <Grid justify="center" container spacing={4}>
          {nameArray.map((name, index) => (
            <Grid item key={index}>
              <Card
                sx={{
                  width: 300,
                  height: 350,
                  marginTop: "1rem",
                  marginBottom: "1rem",
                  marginLeft: "auto",
                  marginRight: "auto",
                  boxShadow: "0px 0px 10px 0px rgba(0,0,0,0.2)",
                  borderRadius: "10px",
                  display: "flex",
                  flexDirection: "column",
                  justifyContent: "center",
                  alignItems: "left",
                  padding: "1rem",
                }}
              >
                <CardContent>
                  <Typography
                    variant="h5"
                    sx={{
                      fontWeight: "bold",
                      fontSize: "1.5rem",
                      color: "text",
                      marginBottom: "1.5rem",
                      textAlign: "left",
                    }}
                  >
                    {nameArray[index]}
                  </Typography>
                  <Typography
                    variant="body2"
                    align="left"
                    sx={{
                      fontSize: "1.5rem",
                      color: "text",
                    }}
                  >
                    {skills[nameArray[index]].map((skill) => (
                        <Grid container spacing={3}>
                          <Grid item>
                            <Typography
                              variant="h5"
                              align="left"
                            >
                              {skill.icon}
                            </Typography>
                          </Grid>
                          <Grid item>
                            <Typography
                              variant="h6"
                              align="left"
                            >
                              {skill.name}
                            </Typography>
                          </Grid>
                        </Grid>
                    ))}
                  </Typography>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>
      </Container>
    </div>
  );
}
